// 
// TOAST
// 
let toastTm;
function toast(msg,type='info',dur=2500){
  const el=document.getElementById('toast');
  const s={info:'background:#EEF2FF;color:#3730A3;border:2px solid #C7D2FE',
    success:'background:#D1FAE5;color:#065F46;border:2px solid #6EE7B7',
    warning:'background:#FEF3C7;color:#92400E;border:2px solid #FCD34D',
    error:'background:#FEE2E2;color:#991B1B;border:2px solid #FCA5A5'};
  const ic={info:'ℹ',success:'✅',warning:'⚠',error:''};
  el.style.cssText+= ';'+s[type];
  el.innerHTML=`<span>${ic[type]}</span> ${msg}`;
  requestAnimationFrame(()=>{el.style.transform='translateY(0)';el.style.opacity='1';});
  clearTimeout(toastTm);
  toastTm=setTimeout(()=>{el.style.transform='translateY(80px)';el.style.opacity='0';},dur);
}

// 
// CLASSIFIER
// 
function classify(feats){
  const scores={};
  for(const[cls,st] of Object.entries(DB.class_stats)){
    let d=0;
    for(let i=0;i<feats.length;i++){
      const z=(feats[i]-st.mean[i])/(st.std[i]+1e-9);
      d+=z*z;
    }
    scores[cls]=d;
  }
  const total=Object.values(scores).reduce((s,v)=>s+Math.exp(-v/10),0);
  const probs={};
  for(const[c,sc] of Object.entries(scores)) probs[c]=Math.exp(-sc/10)/total;
  const best=Object.entries(probs).sort((a,b)=>b[1]-a[1])[0][0];
  return{predicted:best,probs};
}

