let curVals=[...DB.presets.Normal_1];
let sensChart=null;

function initPredict(){
  // Presets bar
  const pb=document.getElementById('presets-bar');
  pb.innerHTML=CLASSES.map(cls=>{
    const m=META[cls];
    return `<button class="preset-btn" style="color:${m.color};border-color:${m.color};background:${m.color}18"
      onclick="loadPreset('${cls}')">${m.icon} ${m.label.replace(' — ',' ')}</button>`;
  }).join('');

  // Sliders
  buildSliders();
  updateSliders();
  // Sens select
  const ss=document.getElementById('sens-sel');
  ss.innerHTML=FEATS.map((f,i)=>`<option value="${i}">${f}</option>`).join('');

  document.getElementById('btn-predict').addEventListener('click',runPredict);
  document.getElementById('btn-reset').addEventListener('click',()=>{
    curVals=[...DB.presets.Normal_1]; updateSliders(); toast('Reset to Normal defaults','info',1500);
  });
  document.getElementById('btn-sens').addEventListener('click',runSens);
}

function buildSliders(){
  document.getElementById('feat-rows').innerHTML=FEATS.map((f,i)=>{
    const info=FEAT_INFO[f];
    const step=['mean','sd','rms'].includes(f)?0.0001:['skewness','kurtosis'].includes(f)?0.01:0.001;
    return `<div class="feat-row">
      <label style="display:flex;flex-direction:column">
        <span class="feat-lbl">${f}</span>
        <span class="feat-desc">${info.desc}</span>
      </label>
      <input type="range" id="sl-${f}" min="${info.min}" max="${info.max}" step="${step}"
        value="${curVals[i]}" oninput="syncFeat('${f}',this.value,false)">
      <input type="number" class="feat-num" id="num-${f}"
        min="${info.min}" max="${info.max}" step="${step}"
        value="${curVals[i]}" oninput="syncFeat('${f}',this.value,true)">
    </div>`;
  }).join('');
}

function syncFeat(f,v,fromNum){
  const idx=FEATS.indexOf(f); curVals[idx]=parseFloat(v)||0;
  const sl=document.getElementById('sl-'+f),num=document.getElementById('num-'+f);
  if(fromNum) sl.value=v; else num.value=parseFloat(v).toFixed(f==='mean'?5:3);
}
function updateSliders(){ FEATS.forEach((f,i)=>{syncFeat(f,curVals[i],true);syncFeat(f,curVals[i],false);}); }
function loadPreset(cls){ curVals=[...DB.presets[cls]]; updateSliders(); toast(`Loaded: ${META[cls].label}`,'info',1500); }

function runPredict(){
  const btn=document.getElementById('btn-predict');
  btn.disabled=true; btn.innerHTML='<div class="spinner" style="width:16px;height:16px;border-width:3px;display:inline-block;margin-right:8px;vertical-align:middle"></div> Classifying…';
  setTimeout(()=>{
    const{predicted,probs}=classify(curVals);
    renderResult(predicted,probs);
    btn.disabled=false; btn.innerHTML='🔮 Predict Fault';
    toast(`Predicted: ${META[predicted].label}`,'success',2000);
  },250);
}

function renderResult(cls,probs){
  const m=META[cls],conf=(probs[cls]*100).toFixed(1),sc=SEV_COLORS[m.sev];
  document.getElementById('res-hero').style.background=`linear-gradient(135deg,${m.color}18,${m.color}10)`;
  document.getElementById('res-icon').textContent=m.icon;
  const rc=document.getElementById('res-cls'); rc.textContent=m.label; rc.style.color=m.color;
  document.getElementById('res-conf').innerHTML=`<span style="color:${m.color};font-size:1.5rem;font-weight:900;font-family:var(--mono)">${conf}%</span>`;
  for(let i=1;i<=3;i++){
    const d=document.getElementById('sd'+i);
    d.className='sev-dot'+(i<=m.sev?' on':'');
    d.style.background=i<=m.sev?sc:'var(--brd)';
    d.style.setProperty('--dc',sc);
  }
  const st=document.getElementById('sev-txt'); st.textContent=SEV_LABELS[m.sev]; st.style.color=sc;
  const sorted=Object.entries(probs).sort((a,b)=>b[1]-a[1]);
  document.getElementById('prob-list').innerHTML=sorted.map(([c,p])=>{
    const cm=META[c],pct=(p*100).toFixed(1),top=c===cls;
    return `<div style="opacity:${top?1:.5}">
      <div class="prob-hd">
        <span style="font-size:.72rem;font-weight:${top?700:500};color:${top?cm.color:'inherit'}">${cm.icon} ${cm.label}</span>
        <span style="font-size:.72rem;font-weight:700;font-family:var(--mono);color:${top?cm.color:'var(--muted)'}">${pct}%</span>
      </div>
      <div class="prob-bg"><div class="prob-fill" style="width:${pct}%;background:${cm.color}"></div></div>
    </div>`;
  }).join('');
}

function runSens(){
  const fi=parseInt(document.getElementById('sens-sel').value);
  const feat=FEATS[fi];
  const info=FEAT_INFO[feat];
  const n=50;
  const step=(info.max-info.min)/(n-1);
  const vals=[],confs=[],preds=[];
  for(let i=0;i<n;i++){
    const v=info.min+i*step; vals.push(v);
    const fv=[...curVals]; fv[fi]=v;
    const{predicted,probs}=classify(fv);
    confs.push(probs[predicted]*100); preds.push(predicted);
  }
  document.getElementById('sens-feat-name').textContent=feat;
  if(sensChart) sensChart.destroy();
  sensChart=new Chart(document.getElementById('sensChart'),{
    type:'line',
    data:{labels:vals.map(v=>v.toFixed(3)),datasets:[{label:'Confidence',data:confs,
      borderColor:'#4F46E5',backgroundColor:'rgba(79,70,229,.08)',borderWidth:2.5,
      fill:true,tension:0.4,pointRadius:0,pointHoverRadius:5}]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false},tooltip:{callbacks:{
        title:items=>`${feat} = ${items[0].label}`,
        label:ctx=>` Confidence: ${ctx.parsed.y.toFixed(1)}%`,
        afterLabel:ctx=>` Prediction: ${META[preds[ctx.dataIndex]]?.label||preds[ctx.dataIndex]}`
      },backgroundColor:'#fff',titleColor:'#0F172A',bodyColor:'#334155',borderColor:'#E2E8F8',borderWidth:2,padding:12}},
      scales:{x:{grid:{display:false},ticks:{maxTicksLimit:8,color:'#94A3B8',font:{size:9}},
        title:{display:true,text:feat,color:'#64748B',font:{weight:700}}},
        y:{grid:{color:'#E2E8F8'},ticks:{callback:v=>v+'%',color:'#94A3B8',font:{size:10}},
        title:{display:true,text:'Confidence (%)',color:'#64748B',font:{weight:700}},min:0,max:100}},
      animation:{duration:400}}
  });
  toast(`Sensitivity for "${feat}" computed`,'success',1500);
}

