function buildHeatmap(){
  const feats=DB.features,mat=DB.corr_matrix;
  function cellColor(v){
    if(v>=0){const t=v;return `rgb(255,${Math.round(255*(1-t*.85))},${Math.round(255*(1-t*.85))})`;}
    else{const t=-v;return `rgb(${Math.round(255*(1-t*.85))},${Math.round(255*(1-t*.85))},255)`;}
  }
  let html=`<table class="hm-table"><thead><tr><th></th>${feats.map(f=>`<th>${f}</th>`).join('')}</tr></thead><tbody>`;
  for(let i=0;i<feats.length;i++){
    html+=`<tr><th style="text-align:right;padding:.45rem .65rem;background:var(--surf2);font-weight:700;color:var(--muted)">${feats[i]}</th>`;
    for(let j=0;j<feats.length;j++){
      const v=mat[i][j],bg=cellColor(v),tc=Math.abs(v)>.5?'#fff':'#0F172A';
      html+=`<td style="background:${bg};color:${tc}">${v.toFixed(2)}</td>`;
    }
    html+=`</tr>`;
  }
  html+=`</tbody></table>`;
  document.getElementById('hm-container').innerHTML=html;
}

function buildCompare(){
  const feat=document.getElementById('cmp-feat').value;
  document.getElementById('cmp-title').textContent=`⚖ "${feat}" across all fault classes`;
  const ctx=document.getElementById('cmpChart');
  if(cmpChartInst) cmpChartInst.destroy();
  cmpChartInst=new Chart(ctx,{
    type:'bar',
    data:{labels:CLASSES.map(c=>META[c].label),datasets:[{
      label:'Mean',data:CLASSES.map(c=>DB.per_class[c][feat].mean),
      backgroundColor:CLASSES.map(c=>META[c].color+'99'),borderColor:CLASSES.map(c=>META[c].color),
      borderWidth:2,borderRadius:8}]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false}},
      scales:{x:{grid:{display:false},ticks:{font:{size:9},maxRotation:30}},
        y:{grid:{color:'#E2E8F8'},title:{display:true,text:feat,color:'#64748B',font:{weight:700}}}},
      animation:{duration:500}}
  });
  document.getElementById('cmp-table').innerHTML=`<thead><tr><th>Class</th><th>Mean</th><th>Std Dev</th><th>Min</th><th>Max</th><th>Q25</th><th>Q75</th></tr></thead>
  <tbody>${CLASSES.map(c=>{
    const s=DB.per_class[c][feat],m=META[c];
    return `<tr><td style="font-family:var(--sans);font-weight:600;font-size:.78rem;color:${m.color}">${m.icon} ${m.label}</td>
      <td>${(+s.mean).toFixed(5)}</td><td>${(+s.std).toFixed(5)}</td>
      <td>${(+s.min).toFixed(5)}</td><td>${(+s.max).toFixed(5)}</td>
      <td>${(+s.q25).toFixed(5)}</td><td>${(+s.q75).toFixed(5)}</td></tr>`;
  }).join('')}</tbody>`;
}

function buildRadar(){
  const ctx=document.getElementById('radarChart');
  if(radarChartInst) radarChartInst.destroy();
  const rfeats=['rms','kurtosis','skewness','crest','sd','form'];
  const allV={};
  rfeats.forEach(f=>{
    const vals=CLASSES.map(c=>DB.per_class[c][f].mean);
    allV[f]={min:Math.min(...vals),max:Math.max(...vals)};
  });
  const norm=(v,f)=>{const{min,max}=allV[f];return max!==min?(v-min)/(max-min):0;};
  const shown=['Normal_1','Ball_021_1','IR_021_1','OR_021_6_1','IR_007_1'];
  radarChartInst=new Chart(ctx,{
    type:'radar',
    data:{labels:rfeats.map(f=>f.toUpperCase()),datasets:shown.map(cls=>{
      const m=META[cls];
      return{label:m.label,data:rfeats.map(f=>norm(DB.per_class[cls][f].mean,f)),
        backgroundColor:m.color+'22',borderColor:m.color,borderWidth:2.5,
        pointBackgroundColor:m.color,pointRadius:4};
    })},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{position:'bottom',labels:{font:{size:10},boxWidth:12,padding:12,color:'#334155'}}},
      scales:{r:{min:0,max:1,ticks:{display:false},grid:{color:'#E2E8F8'},
        pointLabels:{color:'#334155',font:{size:11,weight:700,family:"'JetBrains Mono',monospace"}}}},
      animation:{duration:700}}
  });
}

